/* <stdio.h> for the gcc2 on this disk -- A FORWARD, DELIBERATELY. * * What used to be here was GNU stdio, written against GNU libio: it * declared FILE through <libio.h>, and then * *     extern FILE *stdin, *stdout, *stderr;   [marked TODO] *     #define stdin _IO_stdin *     #define getc(fp) _IO_getc(fp) * * -- its own comment said TODO, and it was never finished.  NO LIBRARY ON * THIS DISK PROVIDES _IO_stdin_, _IO_getc OR _IO_putc.  gcc2 here links * Microware clibn.l, whose streams are _iob and whose FILE has a different * shape entirely.  So any program that so much as named stderr failed at * the link, while printf-only programs happened to work -- which is why it * went unnoticed.  The lua compiler, luac, found it. * * The SDK <stdio.h> is the one matching the library actually linked, so * that is what <stdio.h> means here.  BY ABSOLUTE PATH: plain <stdio.h> * would find this file again, DEFS/GCC2 leading the search. * * NOTE FOR ANYONE EDITING THIS FILE: no apostrophes in the comment.  GNU * cpp reads one as the start of a character constant even in a comment and * dies -- unterminated character constant -- which cost a build here. * -- osk-freeware, 2026-08-23 */#include "/dd/DEFS/stdio.h"